patch_result.patch:
--- a/src/utils/SkPolyUtils.cpp
+++ b/src/utils/SkPolyUtils.cpp
@@ -1511,9 +1511,16 @@

 private:
     int hash(TriangulationVertex* vert) const {
-        int h = (vert->fPosition.fX - fBounds.fLeft)*fGridConversion.fX;
-        int v = (vert->fPosition.fY - fBounds.fTop)*fGridConversion.fY;
-        SkASSERT(v*fHCount + h >= 0);
+        int h = (vert->fPosition.fX - fBounds.fLeft) * fGridConversion.fX;
+        int v = (vert->fPosition.fY - fBounds.fTop) * fGridConversion.fY;
+
+        // Numerical instability and near-collinear/degenerate geometry can place
+        // vertices slightly outside the expected bounds. Clamp to the valid grid
+        // range before indexing into fGrid.
+        h = SkTPin(h, 0, fHCount - 1);
+        v = SkTPin(v, 0, fVCount - 1);
+
+        SkASSERT(v*fHCount + h >= 0 && v*fHCount + h < fGrid.count());
         return v*fHCount + h;
     }

